function validateOrder(f){const e={};if(!f.n?.trim())e.n='Please enter the customer\'s full name.';if(!okph((f.c||'').trim()))e.c='Enter a valid mobile number, e.g. 0917-123-4567.';if(f.ful=='Delivery'&&!f.a?.trim())e.a='Address is required for delivery orders.';if(!validDate(f.d))e.d='Please choose a valid date.';else if(f.d<today())e.d='Date cannot be in the past.';else if(f.m=='Rush (same day)'&&f.d!=today())e.d='Rush orders must be scheduled for today.';if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(f.t||''))e.t='Please choose a valid time.';if(!money(f.l)||!(Number(f.l)>0))e.l='Enter a valid lechon price greater than 0, with at most 2 decimal places.';if(f.ful=='Delivery'&&!money(f.sh))e.sh='Enter a shipping fee of 0 or more, with at most 2 decimal places.';if(!ORDER_TYPES.includes(f.ty))e.ty='Choose Lechon Only or Lechon + Package.';else if(f.ty!='Lechon Only'&&!['350','500','650'].includes(f.bil))e.bil='Choose a bilao or package for this order type.';if(!['Standard','Rush (same day)'].includes(f.m))e.d='Please choose a valid order method.';if(!['Pickup','Delivery'].includes(f.ful))e.a='Please choose Pickup or Delivery.';if(!['COD','GCash'].includes(f.pay))e.l='Please choose a payment method.';return e}
